classdef TestOrbit < matlab.unittest.TestCase
%TESTORBIT Layer L5 test suite — orbit and attitude.
%
%   Covers P14: rotationGcrsToRsw and interpolateQuaternions. The GRACE-FO
%   SCA1B comparison named in risk R20 belongs here once a record is available;
%   until then the convention is pinned by literals computed independently in
%   Python from the conventions transcribed out of the L4b source, never
%   generated by the functions under test.
%
%   The class lives outside +referenceSystem and calls referenceSystem.*
%   explicitly; it must never import the package (handover section C.5 rule 4).
%
% -------------------------------------------------------------------------
% referenceSystem v2.3
% Developed by Matthias Weigelt with the assistance of Claude Opus 5 (Anthropic)
% Created: 2026-07-26 23:05 (CEST, UTC+02:00) - session S5, prompt P14
% -------------------------------------------------------------------------

    properties (Constant)
        % Vallado, Fundamentals of Astrodynamics and Applications, the worked
        % IJK state. Chosen because its flight path angle is 40.7 degrees, so
        % RSW and NTW are far apart and a test that confuses them cannot pass.
        Position = [6524.834; 6862.875; 6448.296]*1e3
        Velocity = [4.901327; 5.533756; -1.976341]*1e3
    end

    methods (Test, TestTags = {'contract'})

        function rotationGcrsToRsw_contract_returnsOnePagePerState(testCase)
            n = 7;
            r = TestOrbit.Position + (1:n)*1e3;
            v = TestOrbit.Velocity + (1:n);
            [R, info] = referenceSystem.rotationGcrsToRsw(r, v);

            testCase.verifySize(R, [3 3 n]);
            testCase.verifyEqual(info.frame, "RSW");
            testCase.verifySize(info.sineOfPlaneAngle, [1 n]);
            testCase.verifyEqual(info.rowAxis, ...
                ["radial", "alongTrack", "crossTrack"]);
        end

        function rotationGcrsToRsw_contract_expandsASingleState(testCase)
            n = 4;
            v = TestOrbit.Velocity + (1:n);
            R = referenceSystem.rotationGcrsToRsw(TestOrbit.Position, v);
            testCase.verifySize(R, [3 3 n]);

            r = TestOrbit.Position + (1:n)*1e3;
            R = referenceSystem.rotationGcrsToRsw(r, TestOrbit.Velocity);
            testCase.verifySize(R, [3 3 n]);
        end

        function rotationGcrsToRsw_contract_rejectsARowLayout(testCase)
            % Decision D65: L5 takes 3xN like L2, never Nx3 like L4. A 3x3 is
            % three states and is accepted; a 4x3 is refused by name.
            testCase.verifyError(@() referenceSystem.rotationGcrsToRsw( ...
                TestOrbit.Position.', TestOrbit.Velocity.'), ...
                'referenceSystem:rotationGcrsToRsw:wrongStateSize');
        end

        function rotationGcrsToRsw_contract_rejectsMismatchedCounts(testCase)
            testCase.verifyError(@() referenceSystem.rotationGcrsToRsw( ...
                repmat(TestOrbit.Position, 1, 3), ...
                repmat(TestOrbit.Velocity, 1, 2)), ...
                'referenceSystem:rotationGcrsToRsw:sizeMismatch');
        end

        function rotationGcrsToRsw_contract_rejectsARadialVelocity(testCase)
            % r x v vanishes: the trajectory is rectilinear and the orbit
            % normal is undefined, not merely ill conditioned.
            radial = TestOrbit.Position;
            testCase.verifyError(@() referenceSystem.rotationGcrsToRsw( ...
                radial, radial*1e-3), ...
                'referenceSystem:rotationGcrsToRsw:degenerateOrbitPlane');
        end

        function rotationGcrsToRsw_contract_rejectsAZeroState(testCase)
            testCase.verifyError(@() referenceSystem.rotationGcrsToRsw( ...
                zeros(3, 1), TestOrbit.Velocity), ...
                'referenceSystem:rotationGcrsToRsw:zeroState');
        end

        function interpolateQuaternions_contract_returnsOneColumnPerQuery(testCase)
            [node, nodeEpoch] = TestOrbit.spinSeries(5, 0:4);
            queryEpoch = TestOrbit.epochAt((0.5:1:3.5));

            [q, convention, info] = referenceSystem.interpolateQuaternions( ...
                node, nodeEpoch, queryEpoch);

            testCase.verifySize(q, [4 4]);
            testCase.verifyEqual(convention.quaternion, "scalarFirst");
            testCase.verifyEqual(info.method, "slerp");
            testCase.verifyEqual(info.nodeCount, 5);
        end

        function interpolateQuaternions_contract_refusesASingleNode(testCase)
            [node, nodeEpoch] = TestOrbit.spinSeries(1, 0);
            testCase.verifyError(@() referenceSystem.interpolateQuaternions( ...
                node, nodeEpoch, nodeEpoch), ...
                'referenceSystem:interpolateQuaternions:tooFewNodes');
        end

        function interpolateQuaternions_contract_refusesExtrapolation(testCase)
            % Nothing in the series constrains an attitude outside it, so it is
            % refused rather than offered behind an option.
            [node, nodeEpoch] = TestOrbit.spinSeries(4, 0:3);
            outside = TestOrbit.epochAt(9);
            testCase.verifyError(@() referenceSystem.interpolateQuaternions( ...
                node, nodeEpoch, outside), ...
                'referenceSystem:interpolateQuaternions:queryOutOfRange');
        end

        function interpolateQuaternions_contract_refusesUnorderedNodes(testCase)
            [node, ~] = TestOrbit.spinSeries(4, 0:3);
            nodeEpoch = TestOrbit.epochAt([0 2 1 3]);
            testCase.verifyError(@() referenceSystem.interpolateQuaternions( ...
                node, nodeEpoch, nodeEpoch), ...
                'referenceSystem:interpolateQuaternions:nodesNotIncreasing');
        end

        function interpolateQuaternions_contract_refusesACountMismatch(testCase)
            [node, ~] = TestOrbit.spinSeries(5, 0:4);
            nodeEpoch = TestOrbit.epochAt((0:3));
            testCase.verifyError(@() referenceSystem.interpolateQuaternions( ...
                node, nodeEpoch, nodeEpoch), ...
                'referenceSystem:interpolateQuaternions:sizeMismatch');
        end

    end

    methods (Test, TestTags = {'reference'})

        function rotationGcrsToRsw_reference_matchesTheValladoState(testCase)
            % Literals computed in Python from r and v directly, not from this
            % function. Row 1 radial, row 2 along-track, row 3 cross-track.
            expected = [ ...
                0.5695276227572369, 0.59903391933497041, 0.56284691560199074; ...
                0.35482589721214886, 0.43849486704214802, -0.82572442996757833; ...
                -0.74144242499609092, 0.66998553347357659, 0.037182191329224332];

            [R, info] = referenceSystem.rotationGcrsToRsw( ...
                TestOrbit.Position, TestOrbit.Velocity);

            testCase.verifyEqual(R, expected, 'AbsTol', 1e-15, ...
                'RSW rotation against the independent Python literal.');
            testCase.verifyEqual(info.sineOfPlaneAngle, 0.75766328710608555, ...
                'AbsTol', 1e-15);
        end

        function rotationGcrsToRsw_reference_ntwIsVelocityAligned(testCase)
            % NTW row 2 is the unit velocity BY DEFINITION, which is the whole
            % difference from RSW and is 40.7 degrees at this state.
            expectedRow2 = [0.64053828070287044, 0.723188343497423, ...
                -0.25828149524049132];

            R = referenceSystem.rotationGcrsToRsw(TestOrbit.Position, ...
                TestOrbit.Velocity, 'Frame', "NTW");

            testCase.verifyEqual(reshape(R(2, :, 1), 1, 3), expectedRow2, ...
                'AbsTol', 1e-15);
            testCase.verifyEqual(reshape(R(2, :, 1), 3, 1), ...
                TestOrbit.Velocity/norm(TestOrbit.Velocity), 'AbsTol', 1e-15);
        end

        function rotationGcrsToRsw_reference_alongTrackIsNotTheVelocity(testCase)
            % The trap this frame exists to make visible: choosing RSW where
            % NTW was meant is silent, plausible and wrong by the flight path
            % angle. Assert the two DIFFER, so a code change that quietly
            % aliased them would fail here.
            rsw = referenceSystem.rotationGcrsToRsw(TestOrbit.Position, ...
                TestOrbit.Velocity, 'Frame', "RSW");
            ntw = referenceSystem.rotationGcrsToRsw(TestOrbit.Position, ...
                TestOrbit.Velocity, 'Frame', "NTW");

            separation = acos(min(1, abs(rsw(2, :, 1)*ntw(2, :, 1).')));
            testCase.verifyEqual(rad2deg(separation), 40.74137075567535, ...
                'AbsTol', 1e-9, 'Flight path angle of the Vallado state.');
        end

        function rotationGcrsToRsw_reference_circularOrbitCollapsesTheFrames(testCase)
            % On a circular orbit the flight path angle is zero, so RSW's
            % along-track IS the velocity direction. Exact, not approximate.
            r = [7000e3; 0; 0];
            v = [0; 7546.0532; 0];
            R = referenceSystem.rotationGcrsToRsw(r, v);

            testCase.verifyEqual(reshape(R(2, :, 1), 3, 1), v/norm(v), ...
                'AbsTol', 1e-16);
        end

        function interpolateQuaternions_reference_slerpIsConstantRate(testCase)
            % A rotation about a fixed axis: SLERP must return the linearly
            % interpolated ANGLE, which is the definition of constant rate.
            % Literals are cos and sin of half of 25 and 40 degrees.
            node = TestOrbit.axisQuaternion([10 70]);
            nodeEpoch = TestOrbit.epochAt([0 4]);
            queryEpoch = TestOrbit.epochAt([1 2]);

            q = referenceSystem.interpolateQuaternions(node, nodeEpoch, ...
                queryEpoch);

            expected = [0.97629600711993336, 0.93969262078590843; ...
                0, 0; 0, 0; ...
                0.21643961393810288, 0.34202014332566871];
            testCase.verifyEqual(q, expected, 'AbsTol', 1e-15, ...
                'SLERP at quarter and half of a 10 to 70 degree turn.');
        end

    end

    methods (Test, TestTags = {'precision'})

        function rotationGcrsToRsw_precision_everyFrameIsOrthonormal(testCase)
            rng(541);
            n = 200;
            r = TestOrbit.Position + (rand(3, n) - 0.5)*2e6;
            v = TestOrbit.Velocity + (rand(3, n) - 0.5)*2e3;

            for frame = ["RSW", "LVLH", "NTW"]
                R = referenceSystem.rotationGcrsToRsw(r, v, 'Frame', frame);
                residual = pagemtimes(R, 'transpose', R, 'none') - eye(3);
                % A few ulp of a three-term dot product of unit vectors.
                testCase.verifyLessThan(max(abs(residual), [], 'all'), 1e-14, ...
                    "Orthogonality of " + frame);

                determinant = zeros(1, n);
                for k = 1:n
                    determinant(k) = det(R(:, :, k));
                end
                testCase.verifyEqual(determinant, ones(1, n), 'AbsTol', 1e-14, ...
                    "Right handedness of " + frame + ...
                    ": the LVLH sign changes must come in pairs.");
            end
        end

        function interpolateQuaternions_precision_reproducesTheNodes(testCase)
            % u = 0 and u = 1 give sin(0)/sin(w) and sin(w)/sin(w) exactly, so
            % the nodes come back unchanged and not merely closely.
            [node, nodeEpoch] = TestOrbit.spinSeries(6, 0:5);

            for method = ["slerp", "squad"]
                q = referenceSystem.interpolateQuaternions(node, nodeEpoch, ...
                    nodeEpoch, 'Method', method);
                testCase.verifyEqual(q, node, 'AbsTol', 1e-15, ...
                    "Nodes reproduced by " + method);
            end
        end

        function interpolateQuaternions_precision_takesTheShortWayAt179(testCase)
            % SEAM ITEM 4. A 179 degree pair has a short way of 89.5 degrees to
            % the midpoint and a long way of 90.5. The naive great circle
            % through a sign-flipped operand takes the long one.
            node = TestOrbit.axisQuaternion([0 179]);
            nodeEpoch = TestOrbit.epochAt([0 2]);
            queryEpoch = TestOrbit.epochAt(1);

            q = referenceSystem.interpolateQuaternions(node, nodeEpoch, ...
                queryEpoch);

            angleFromFirst = 2*acos(min(1, abs(q.'*node(:, 1))));
            testCase.verifyEqual(rad2deg(angleFromFirst), 89.5, ...
                'AbsTol', 1e-12, ...
                'Half of 179 degrees, never half of 181.');
        end

        function interpolateQuaternions_precision_undoesASignFlip(testCase)
            % SEAM ITEM 4. q and -q are the same rotation, so a series read
            % from a file may flip with no change in attitude. Interpolating
            % across the flip would sweep up to 360 degrees of fiction while
            % every node stayed correct.
            node = TestOrbit.axisQuaternion([0 60 120]);
            flipped = node;
            flipped(:, 2) = -flipped(:, 2);
            nodeEpoch = TestOrbit.epochAt([0 1 2]);
            queryEpoch = TestOrbit.epochAt(0:0.25:2);

            [clean, ~, cleanInfo] = referenceSystem.interpolateQuaternions( ...
                node, nodeEpoch, queryEpoch);
            [repaired, ~, repairedInfo] = ...
                referenceSystem.interpolateQuaternions(flipped, nodeEpoch, ...
                queryEpoch);

            testCase.verifyEqual(cleanInfo.signFlipCount, 0);
            testCase.verifyGreaterThan(repairedInfo.signFlipCount, 0, ...
                'The flip must be detected, not absorbed silently.');
            % Same physical attitude at every query point, up to the sign.
            testCase.verifyEqual(abs(sum(clean.*repaired, 1)), ...
                ones(1, size(clean, 2)), 'AbsTol', 1e-14, ...
                'A sign flip must not change the interpolated rotation.');
        end

        function interpolateQuaternions_precision_squadIsSmootherThanSlerp(testCase)
            % SLERP is only C0: the rate jumps at every node, which is
            % invisible in the attitude and obvious once differentiated. The
            % claim in the ACCURACY block is that SQUAD reduces that jump by
            % orders of magnitude, so it is asserted as a ratio.
            [node, nodeEpoch] = TestOrbit.spinSeries(9, 0:8);
            step = 1e-3;
            centre = 4;
            queryEpoch = TestOrbit.epochAt(centre + [-2 -1 1 2]*step);

            jump = zeros(1, 2);
            method = ["slerp", "squad"];
            for k = 1:2
                q = referenceSystem.interpolateQuaternions(node, nodeEpoch, ...
                    queryEpoch, 'Method', method(k));
                before = (q(:, 2) - q(:, 1))/step;
                after = (q(:, 4) - q(:, 3))/step;
                jump(k) = norm(after - before);
            end

            testCase.verifyLessThan(jump(2), jump(1)/100, sprintf( ...
                ['Rate discontinuity at an interior node: slerp %.3e, ', ...
                'squad %.3e. SQUAD must be at least 100 times smoother.'], ...
                jump(1), jump(2)));
        end

        function interpolateQuaternions_precision_outputIsOfUnitNorm(testCase)
            % 1e-15 is a few ulp of unity through a square root of four squares of unit
            % components. It bounds the renormalisation, not the interpolation error, which is
            % measured separately against held-out real attitude.
            [node, nodeEpoch] = TestOrbit.spinSeries(7, 0:6);
            queryEpoch = TestOrbit.epochAt(0:0.1:6);

            for method = ["slerp", "squad"]
                q = referenceSystem.interpolateQuaternions(node, nodeEpoch, ...
                    queryEpoch, 'Method', method);
                testCase.verifyEqual(sqrt(sum(q.^2, 1)), ...
                    ones(1, size(q, 2)), 'AbsTol', 1e-15, ...
                    "Unit norm after " + method);
            end
        end

    end

    methods (Test, TestTags = {'vectorization'})

        function rotationGcrsToRsw_vectorization_batchEqualsTheLoop(testCase)
            rng(547);
            n = 40;
            r = TestOrbit.Position + (rand(3, n) - 0.5)*1e6;
            v = TestOrbit.Velocity + (rand(3, n) - 0.5)*1e3;

            batch = referenceSystem.rotationGcrsToRsw(r, v);
            for k = 1:n
                single = referenceSystem.rotationGcrsToRsw(r(:, k), v(:, k));
                % Elementwise arithmetic throughout, no matrix product, so
                % bit identity is a claim about this function and is sound
                % here where obligation O13 forbids it across BLAS.
                testCase.verifyEqual(batch(:, :, k), single, 'AbsTol', 0, ...
                    sprintf('State %d differs between batch and single.', k));
            end
        end

        function interpolateQuaternions_vectorization_batchEqualsTheLoop(testCase)
            % 1e-15 rather than zero: one ulp of a unit quaternion component. The batch and the
            % single query take the same arithmetic path but the node search may resolve its
            % bracket in a different order, so bit identity is not claimed (obligation O13).
            [node, nodeEpoch] = TestOrbit.spinSeries(6, 0:5);
            fraction = (0:0.2:5);
            queryEpoch = TestOrbit.epochAt(fraction);

            batch = referenceSystem.interpolateQuaternions(node, nodeEpoch, ...
                queryEpoch, 'Method', "squad");
            for k = 1:numel(fraction)
                one = TestOrbit.epochAt(fraction(k));
                single = referenceSystem.interpolateQuaternions(node, ...
                    nodeEpoch, one, 'Method', "squad");
                testCase.verifyEqual(batch(:, k), single, 'AbsTol', 1e-15, ...
                    sprintf('Query %d differs between batch and single.', k));
            end
        end

    end

    methods (Static, Access = private)


        function epoch = epochAt(offsetSecond)
            %EPOCHAT An epoch series at MJD 60000 TAI, offset in SECONDS.
            %   D9: an offset folded into the day number is quantised to
            %   eps(60000) = 6.3e-07 s, which is 2e-08 rad of interpolated
            %   attitude - seven orders above the tolerances here. The day
            %   number is therefore repeated and the offset added in seconds,
            %   which addSeconds requires one-per-entry: it advances an
            %   existing series and does not expand a scalar epoch into one.
            offsetSecond = reshape(offsetSecond, [], 1);
            epoch = referenceSystem.addSeconds( ...
                referenceSystem.mjdToEpoch( ...
                    repmat(60000, numel(offsetSecond), 1), "TAI"), ...
                offsetSecond);
        end

        function q = axisQuaternion(angleDegree)
            %AXISQUATERNION Rotations about z through the given angles.
            %   Built here from cos and sin rather than through any package
            %   function, so a reference test does not compare the toolbox
            %   against itself.
            half = deg2rad(reshape(angleDegree, 1, []))/2;
            q = [cos(half); zeros(2, numel(half)); sin(half)];
        end

        function [q, epoch] = spinSeries(count, second)
            %SPINSERIES A smoothly turning attitude series and its epochs.
            %   The axis itself turns, so the series is not a single-axis
            %   rotation and SQUAD has something to be smoother than.
            t = reshape(second, 1, []);
            angle = 0.35*t;
            axis = [cos(0.11*t); sin(0.11*t); 0.4*ones(1, numel(t))];
            axis = axis./sqrt(sum(axis.^2, 1));
            q = [cos(angle/2); axis.*sin(angle/2)];
            q = q(:, 1:count);
            epoch = TestOrbit.epochAt(t(1:count));
        end

    end

    methods (Test, TestTags = {'reference'})


        function rotationGcrsToRsw_reference_graceFoSpacecraftAxes(testCase)
            % THE R20 CLOSER, and the strongest test in the toolbox. Real
            % GRACE-FO attitude and the real orbit it was flying, from two
            % independent JPL products, at the same eleven epochs.
            %
            % rotationGcrsToRsw builds the radial / along-track / cross-track
            % frame from position and velocity alone. rotationFromQuaternion
            % builds the spacecraft frame from the star camera quaternion
            % alone. Neither knows about the other. If both conventions are
            % right the two frames must line up axis for axis, because GRACE's
            % science frame IS an orbit frame: X along the line of sight to
            % the twin, Y cross-track, Z radial.
            %
            % Measured over one full orbit at 30 s sampling: SRF 1 sits 1.20
            % deg from along-track, SRF 2 sits 1.61 deg from cross-track, SRF
            % 3 sits 0.99 deg from radial. Those residuals are the attitude
            % control deadband of a real spacecraft, not numerical error.
            %
            % A TRANSPOSED SENSE WOULD SCATTER THIS COMPLETELY. The mapping
            % below is only coherent because the rows of both matrices carry
            % the frame axes in inertial coordinates, which is what the frame
            % sense means.
            state = TestPerformance.graceFoOrbitArc();
            q = TestPerformance.graceFoArc();

            Rrsw = referenceSystem.rotationGcrsToRsw(state(1:3, :), ...
                state(4:6, :));
            Rsrf = referenceSystem.rotationFromQuaternion(q);

            % Pair each spacecraft axis with the orbit axis it is nearest.
            % Expected pairing, from the GRACE science frame definition:
            % SRF 1 -> along-track (2), SRF 2 -> cross-track (3), SRF 3 ->
            % radial (1).
            expected = [2 3 1];
            for k = 1:3
                angle = zeros(1, 3);
                for j = 1:3
                    inner = abs(sum(squeeze(Rsrf(k, :, :)).* ...
                        squeeze(Rrsw(j, :, :)), 1));
                    angle(j) = mean(acosd(min(1, inner)));
                end
                [nearest, which] = min(angle);
                testCase.verifyEqual(which, expected(k), sprintf( ...
                    'SRF axis %d must pair with orbit axis %d.', k, ...
                    expected(k)));
                % Bound: 5 deg. Measured 0.99 to 1.61 deg over a full orbit,
                % and the next-nearest axis is always near 89 deg, so this
                % separates the pairing by more than an order of magnitude
                % without asserting the spacecraft's pointing performance.
                testCase.verifyLessThan(nearest, 5, sprintf( ...
                    'SRF axis %d is %.2f deg from its orbit axis.', k, ...
                    nearest));
            end
        end

        function interpolateQuaternions_reference_graceFoStarCamera(testCase)
            % REAL FLIGHT ATTITUDE - the R20 mitigation the register asks for
            % by name. Nothing here is derived from the toolbox: the
            % quaternions are a verbatim SCA1B extract and the assertions are
            % properties of the spacecraft, not of the code.
            q = TestPerformance.graceFoArc();

            testCase.verifyEqual(sqrt(sum(q.^2, 1)), ones(1, 11), ...
                'AbsTol', 1e-9, 'JPL ships unit quaternions.');

            % THE DELIVERED SERIES HAS NO SIGN REVERSALS and five of these
            % eleven records have q0 < 0. Imposing the canonical form would
            % flip those five and inject discontinuities into a series that
            % has none - which is what this function did to its nodes before
            % run 1 of S5. signFlipCount must therefore be zero.
            [interpolated, ~, info] = referenceSystem.interpolateQuaternions( ...
                q(:, 1:2:end), TestOrbit.epochAt(0:2:10), ...
                TestOrbit.epochAt(1:2:9));

            testCase.verifyEqual(info.signFlipCount, 0, ...
                'Real SCA1B is sign continuous; nothing may be repaired.');

            % Held-out truth: the even-numbered records were never shown to
            % the interpolator. Bound: 5e-05 rad is 10 arcsec, above the
            % 2.3e-05 measured here and far above JPL's 8.8e-07 formal error,
            % so it bounds the method rather than the data.
            heldOut = q(:, 2:2:10);
            angle = 2*acos(min(1, abs(sum(interpolated.*heldOut, 1))));
            testCase.verifyLessThan(max(angle), 5e-05, ...
                'SLERP across a 2 s gap in real star camera attitude.');
        end

    end


    methods (Test, TestTags = {'speed'})

        function interpolateQuaternions_speed_oneDayOfStarCamera(testCase)
            % LAYER L5 HAD NO BENCHMARK. This is the L5 workload that actually
            % costs something in a reprocessing campaign: an SCA1B day is 86 400
            % records at 1 Hz, and a science pipeline resamples it onto the
            % accelerometer or KBR grid, which is a query per node.
            %
            % 0.052 s, RE-DERIVED AT REV. 1.250 FROM THE SLOWEST OF THREE
            % MEASURED MEDIANS, 0.025895 s - see the class help of
            % TestPerformance for the runs and the rule. It replaces the 0.20 s
            % of rev. 1.76, which was twice 0.058 s on the PCWIN64 of the day
            % rounded up generously; this runner does the same work in 0.026 s,
            % so the old target had drifted to 7.7x the cost. The rev. 1.73
            % prediction of 1.0 s was pessimistic by 39x on today's host,
            % because it budgeted for a per-query search that the vectorised
            % implementation does not perform.
            targetSeconds = 0.052;
            nodeCount = 86400;
            second = (0:nodeCount - 1)';
            nodeEpoch = TestOrbit.epochAt(second);
            angle = 2 * pi * second / 5400;
            q = referenceSystem.normalizeQuaternion([cos(angle / 2)'; ...
                sin(angle / 2)' * 0.3; sin(angle / 2)' * 0.5; ...
                sin(angle / 2)' * 0.8]);
            queryEpoch = TestOrbit.epochAt(second(1:end - 1) + 0.5);

            medianSeconds = TestPerformance.medianDuration(@() ...
                referenceSystem.interpolateQuaternions(q, nodeEpoch, queryEpoch), 3);

            testCase.log(matlab.unittest.Verbosity.Concise, ...
                TestPerformance.benchmarkRecord("interpolateQuaternions", ...
                nodeCount, medianSeconds, targetSeconds));
            if medianSeconds > targetSeconds
                warning('referenceSystem:test:slowerThanTarget', ...
                    'interpolateQuaternions took %.3f s against a %.3f s target.', ...
                    medianSeconds, targetSeconds);
            end
            testCase.verifyLessThan(medianSeconds, 5 * targetSeconds);
        end

    end


    methods (Test, TestTags = {'contract'})

        % ISSUE #25 NAMES THE SEVEN CATEGORIES OF THE PREPARATION CONCEPT, AND
        % THIS TOOLBOX HAS TEN TAGS, NOT THOSE SEVEN (handover section D.1).
        % The mapping is stated once, here, rather than invented per test:
        % robustness is 'contract', which is where a documented refusal and an
        % edge shape belong, and metamorphic is 'precision', which is where a
        % relation between two runs of the same function belongs. Nothing is
        % dropped by the mapping; only the labels differ.

        function orbitSunGeometry_contract_returnsOnePerState(testCase)
            % The one tolerance here bounds a NORMALISATION and nothing
            % physical: info.sunDirection is the Sun vector divided by its own
            % length, so its norm is 1 to a few units in the last place.
            % 1e-15 is about four of them at unit magnitude, which is the
            % rounding of that division and admits no error in the direction.
            [r, v] = TestOrbit.circularState(89, 30, 0:60:300);
            [beta, u, info] = referenceSystem.orbitSunGeometry(r, v, ...
                TestOrbit.j2000Epoch(6));

            testCase.verifySize(beta, [1 6]);
            testCase.verifySize(u, [1 6]);
            testCase.verifySize(info.sunDirection, [3 6]);
            testCase.verifySize(info.uSun, [1 6]);
            testCase.verifySize(info.sineOfPlaneAngle, [1 6]);
            testCase.verifySize(info.sineOfNodeAngle, [1 6]);
            testCase.verifyEqual(info.equator, "cip");

            testCase.verifyGreaterThanOrEqual(beta, -pi/2);
            testCase.verifyLessThanOrEqual(beta, pi/2);
            testCase.verifyGreaterThanOrEqual(u, 0);
            testCase.verifyLessThan(u, 2*pi);
            testCase.verifyEqual(sqrt(sum(info.sunDirection.^2, 1)), ...
                ones(1, 6), 'AbsTol', 1e-15, ...
                'The reported Sun direction must be a unit vector.');
        end

        function orbitSunGeometry_contract_expandsASingleEpoch(testCase)
            % One instant, six states: a caller sampling an orbit at one epoch
            % should not have to build six identical epochs to say so.
            [r, v] = TestOrbit.circularState(89, 30, 0:60:300);
            [beta, u] = referenceSystem.orbitSunGeometry(r, v, ...
                TestOrbit.j2000Epoch(1));

            testCase.verifySize(beta, [1 6]);
            testCase.verifySize(u, [1 6]);
            % The orbit normal is one vector, so one beta serves all six.
            testCase.verifyEqual(beta, repmat(beta(1), 1, 6), 'AbsTol', 1e-15);
        end

        function orbitSunGeometry_contract_rejectsARowLayout(testCase)
            % Decision D65 again: L5 takes 3xN like L2, never Nx3 like L4.
            [r, v] = TestOrbit.circularState(89, 30, 0:90:270);
            testCase.verifyError(@() referenceSystem.orbitSunGeometry( ...
                r.', v.', TestOrbit.j2000Epoch(4)), ...
                'referenceSystem:orbitSunGeometry:wrongStateSize');
        end

        function orbitSunGeometry_contract_rejectsMismatchedCounts(testCase)
            [r, v] = TestOrbit.circularState(89, 30, 0:90:270);
            testCase.verifyError(@() referenceSystem.orbitSunGeometry( ...
                r, v, TestOrbit.j2000Epoch(3)), ...
                'referenceSystem:orbitSunGeometry:sizeMismatch');
        end

        function orbitSunGeometry_contract_refusesUt1(testCase)
            % UT1 is an angle, not a uniform time: neither the Sun nor the
            % precession-nutation model can be evaluated at it.
            [r, v] = TestOrbit.circularState(89, 30, 0);
            ut1 = referenceSystem.daySecondToEpoch([51544 43200], "UT1");
            testCase.verifyError(@() referenceSystem.orbitSunGeometry( ...
                r, v, ut1), 'referenceSystem:orbitSunGeometry:wrongScale');
        end

        function orbitSunGeometry_contract_refusesAnEquatorialOrbit(testCase)
            % k x h vanishes: the orbit lies in the chosen equator, so it has
            % no ascending node and u has no origin. Refused by its own name,
            % not measured from an arbitrary axis.
            [r, v] = TestOrbit.circularState(0, 0, 0);
            testCase.verifyError(@() referenceSystem.orbitSunGeometry( ...
                r, v, TestOrbit.j2000Epoch(1), 'Equator', "gcrs"), ...
                'referenceSystem:orbitSunGeometry:undefinedNode');
        end

        function orbitSunGeometry_contract_refusesARadialVelocity(testCase)
            % The orbit normal itself does not exist, so the refusal is the
            % orbit frame's and carries ITS identifier - this function does
            % not rebuild the triad and must not invent a second name for the
            % same condition.
            [r, ~] = TestOrbit.circularState(89, 30, 0);
            testCase.verifyError(@() referenceSystem.orbitSunGeometry( ...
                r, r*1e-3, TestOrbit.j2000Epoch(1)), ...
                'referenceSystem:rotationGcrsToRsw:degenerateOrbitPlane');
        end

        function orbitSunGeometry_contract_refusesAnUnknownEquator(testCase)
            [r, v] = TestOrbit.circularState(89, 30, 0);
            testCase.verifyError(@() referenceSystem.orbitSunGeometry( ...
                r, v, TestOrbit.j2000Epoch(1), 'Equator', "j2000"), ...
                'MATLAB:validators:mustBeMember');
        end

    end


    methods (Test, TestTags = {'reference'})

        function orbitSunGeometry_reference_argumentOfLatitude(testCase)
            % INDEPENDENT ORACLE, AND NOT THE CONSTRUCTION THAT MADE THE
            % STATES. The literals below come from numpy, by the textbook
            % route of Vallado Sect. 2.4: the inclination and the right
            % ascension of the node are recovered from h = r x v, and then
            %
            %     u = atan2(z/sin i, x cos RAAN + y sin RAAN),
            %
            % which is a different expression from the vector form the
            % function evaluates. The states themselves are hardcoded, so
            % MATLAB never runs the construction either.
            %
            % Tolerance: the geometry is four normalisations and an arc
            % tangent, so it is roundoff. A 1e-9 m component of a 6.87e6 m
            % radius is 1.5e-16 rad; 1e-12 bounds that with three decades to
            % spare and bounds nothing else.
            [r, v] = TestOrbit.referenceStates();
            expected = [0, 0.78539816339744817, 1.5707963267948966, ...
                3.1415926535897931, 4.7123889803846897];

            [~, u] = referenceSystem.orbitSunGeometry(r, v, ...
                TestOrbit.j2000Epoch(5), 'Equator', "gcrs");

            testCase.verifyEqual(u, expected, 'AbsTol', 1e-12);
        end

        function orbitSunGeometry_reference_betaAgainstTheAlmanacSun(testCase)
            % THE SUN COMES FROM AN INDEPENDENT PUBLISHED SOURCE, NOT FROM
            % THIS TOOLBOX. The Astronomical Almanac's low-precision solar
            % coordinates give the Sun to 0.01 degrees over 1950-2050; beta
            % and uSun below were formed from that direction in numpy.
            %
            % THE EPOCH IS J2000.0 EXACTLY, AND THAT IS WHY THE COMPARISON IS
            % LEGITIMATE. The Almanac formula is referred to the mean equinox
            % of date, which differs from the GCRS by precession - about 0.11
            % degrees by 2020, ten times the formula's own accuracy. At
            % J2000.0 the two differ by the frame bias alone, 23 mas, which is
            % 1.1e-7 rad and negligible here.
            %
            % Tolerance, one term at a time: 0.01 deg formula accuracy is
            % 1.75e-4 rad; the Almanac series is apparent and this toolbox
            % returns a geometric direction, which is aberration at 20.5
            % arcsec, or 9.9e-5 rad; frame bias 1.1e-7 rad. The sum is 2.8e-4
            % and 4e-4 rounds it up. Nothing in it is the orbit geometry,
            % which is exact, so this bounds the SUN and a sign error or an
            % axis swap in beta is orders of magnitude outside it.
            [r, v] = TestOrbit.referenceStates();
            [beta, ~, info] = referenceSystem.orbitSunGeometry(r, v, ...
                TestOrbit.j2000Epoch(5), 'Equator', "gcrs");

            testCase.verifyEqual(beta, repmat(1.0444757698576079, 1, 5), ...
                'AbsTol', 4e-4);
            testCase.verifyEqual(info.uSun, ...
                repmat(4.0840924119785402, 1, 5), 'AbsTol', 4e-4);

            almanac = [0.18010164163354572; -0.90248138840147263; ...
                -0.39126812069200367];
            separation = acos(min(1, info.sunDirection(:, 1).'*almanac));
            testCase.verifyLessThan(separation, 4e-4, ...
                'The toolbox Sun and the Almanac Sun must agree at J2000.0.');
            testCase.log(1, TestPerformance.noteRecord("orbitSunGeometry", ...
                sprintf("sunSeparation=%.3e rad", separation), ...
                "toolbox Sun against the Astronomical Almanac at J2000.0"));
        end

    end


    methods (Test, TestTags = {'precision'})

        function orbitSunGeometry_precision_theClassicalBetaFormula(testCase)
            % The published spherical form,
            %
            %   sin beta = cos dec sin i sin(RAAN - ra) + sin dec cos i,
            %
            % evaluated from the Sun's right ascension and declination and the
            % orbit's inclination and node, against the vector form the
            % function uses. The two are algebraically the same statement, so
            % what this pins is the SIGN CONVENTION and the transcription -
            % the part of a published formula that is actually got wrong.
            [r, v] = TestOrbit.referenceStates();
            [beta, ~, info] = referenceSystem.orbitSunGeometry(r, v, ...
                TestOrbit.j2000Epoch(5), 'Equator', "gcrs");

            momentum = cross(r, v, 1);
            momentum = momentum./sqrt(sum(momentum.^2, 1));
            inclination = acos(momentum(3, :));
            node = atan2(momentum(1, :), -momentum(2, :));
            rightAscension = atan2(info.sunDirection(2, :), ...
                info.sunDirection(1, :));
            declination = asin(info.sunDirection(3, :));

            classical = asin(cos(declination).*sin(inclination).* ...
                sin(node - rightAscension) + sin(declination).* ...
                cos(inclination));

            % Both routes are a handful of transcendental calls on unit-norm
            % quantities, so the difference is accumulated roundoff: 1e-12
            % bounds it and bounds no convention error.
            testCase.verifyEqual(beta, classical, 'AbsTol', 1e-12);
        end

        function orbitSunGeometry_precision_betaIgnoresTheEquator(testCase)
            % beta = asin(h . s) contains no pole at all, so the two equators
            % must give BITWISE the same angle. An implementation that let the
            % equator leak into beta would fail here and nowhere else.
            % 2020 AND NOT J2000.0: at J2000.0 the two equators coincide to
            % within the frame bias, so the test would pass on a function
            % that ignored the equator entirely. It has to run where they
            % differ for the BITWISE claim to mean anything.
            [r, v] = TestOrbit.circularState(89, 30, 0:45:315);
            epoch = TestOrbit.epochIn2020(8);

            betaCip = referenceSystem.orbitSunGeometry(r, v, epoch);
            betaGcrs = referenceSystem.orbitSunGeometry(r, v, epoch, ...
                'Equator', "gcrs");

            testCase.verifyEqual(betaCip, betaGcrs, ...
                'beta must not depend on which equator defines the node.');
        end

        function orbitSunGeometry_precision_theTwoEquatorsDiffer(testCase)
            % THE MEASUREMENT ISSUE #25 ASKS FOR, WITH A DERIVED BOUND RATHER
            % THAN A QUOTED ONE. Tilting the reference pole by a small vector
            % dk rotates the node within the orbit plane by (dk . n)/|k x h|
            % to first order, so the shift in u is at most the pole offset
            % divided by that margin. The offset is read from cipCoordinates
            % at run time, so this tolerance re-derives itself as the model or
            % the epoch changes and can never become a stale literal.
            %
            % The issue asked for a real 2020-01-01 GNV1B arc. The repository
            % carries no orbit fixture and section D.2 forbids a test that
            % fetches one, so a synthetic near-polar orbit stands in - and the
            % quantity measured is a property of the two EQUATORS and of the
            % inclination, not of the orbit product, so nothing is lost.
            % The epoch is 2020-01-01, which is the one the issue names:
            % precession had moved the pole by about 400 arcseconds by then,
            % where at J2000.0 it has moved by the frame bias alone and there
            % would be nothing to measure.
            [r, v] = TestOrbit.circularState(89, 30, 0:45:315);
            epoch = TestOrbit.epochIn2020(8);

            [~, uCip, infoCip] = referenceSystem.orbitSunGeometry(r, v, epoch);
            [~, uGcrs] = referenceSystem.orbitSunGeometry(r, v, epoch, ...
                'Equator', "gcrs");

            shift = abs(mod(uCip - uGcrs + pi, 2*pi) - pi);
            [poleX, poleY] = referenceSystem.cipCoordinates( ...
                referenceSystem.convertTimeScale(epoch, "TT"));
            poleOffset = hypot(poleX, poleY).';
            bound = poleOffset./infoCip.sineOfNodeAngle;

            testCase.verifyLessThanOrEqual(shift, 1.02*bound, ...
                'The u shift exceeds the first-order pole-offset bound.');
            testCase.verifyGreaterThan(min(shift), 0.1*max(bound), ...
                ['The two equators gave the same u, so one of them is not ', ...
                'being applied and the option is untested.']);
            testCase.log(1, TestPerformance.noteRecord("orbitSunGeometry", ...
                sprintf("uShiftCipMinusGcrs=%.4e rad (%.4f deg), bound %.4e", ...
                mean(shift), rad2deg(mean(shift)), mean(bound)), ...
                "measured difference between the CIP and GCRS equators"));
        end

        function orbitSunGeometry_precision_reversingTheVelocity(testCase)
            % Reversing v reverses h, so beta changes sign; the node reverses
            % with it while the in-plane quarter-turn axis does not, which
            % sends u to pi - u. Both halves are asserted: a sign test that
            % checked only beta would pass an implementation that had lost
            % track of the node entirely.
            [r, v] = TestOrbit.circularState(89, 30, 0:45:315);
            epoch = TestOrbit.j2000Epoch(8);

            [beta, u] = referenceSystem.orbitSunGeometry(r, v, epoch, ...
                'Equator', "gcrs");
            [betaReversed, uReversed] = referenceSystem.orbitSunGeometry( ...
                r, -v, epoch, 'Equator', "gcrs");

            testCase.verifyEqual(betaReversed, -beta, 'AbsTol', 1e-15);
            testCase.verifyEqual(mod(uReversed + u, 2*pi), ...
                mod(repmat(pi, 1, 8), 2*pi), 'AbsTol', 1e-12);
        end

        function orbitSunGeometry_precision_rotatingAboutThePole(testCase)
            % Turning the whole orbit about the pole of the chosen equator
            % carries the node with it, so u is unchanged. This is what
            % separates an argument of latitude from an angle measured off a
            % fixed axis, and it is the relation an implementation that
            % hardcoded the x axis would fail.
            epoch = TestOrbit.j2000Epoch(6);
            [r, v] = TestOrbit.circularState(89, 30, 0:60:300);
            [rTurned, vTurned] = TestOrbit.circularState(89, 137, 0:60:300);

            [~, u] = referenceSystem.orbitSunGeometry(r, v, epoch, ...
                'Equator', "gcrs");
            [~, uTurned] = referenceSystem.orbitSunGeometry( ...
                rTurned, vTurned, epoch, 'Equator', "gcrs");

            testCase.verifyEqual(uTurned, u, 'AbsTol', 1e-12);
        end

        function orbitSunGeometry_precision_theCipPoleIsTheCirsThirdRow(testCase)
            % The help of orbitSunGeometry says the CIP direction is taken
            % from the DEFINITION of X and Y rather than from a rotation, and
            % that the equality with rotationGcrsToCirs is asserted by a test
            % rather than relied on by the code. This is that test.
            epoch = referenceSystem.convertTimeScale( ...
                TestOrbit.j2000Epoch(4), "TT");
            [poleX, poleY, locator] = referenceSystem.cipCoordinates(epoch);
            rotation = referenceSystem.rotationGcrsToCirs(poleX, poleY, ...
                locator);

            fromRotation = permute(rotation(3, :, :), [2 3 1]);
            fromDefinition = [poleX.'; poleY.'; ...
                sqrt(1 - poleX.'.^2 - poleY.'.^2)];

            testCase.verifyEqual(fromRotation, fromDefinition, ...
                'AbsTol', 1e-15, ...
                'X and Y are the GCRS components of the CIP by definition.');
        end

    end


    methods (Test, TestTags = {'vectorization'})

        function orbitSunGeometry_vectorization_batchEqualsTheLoop(testCase)
            % 1e-15 rad AND NOT ZERO, deliberately. The geometry here is
            % elementwise and would be bit identical, but the Sun and the CIP
            % are evaluated in C, where changing the batch length may change
            % how the loop is vectorised even though the arithmetic per epoch
            % is the same. One ulp of an angle of order 1 rad bounds that and
            % admits no algorithmic difference.
            [r, v] = TestOrbit.circularState(89, 30, 0:36:324);
            epoch = TestOrbit.epochIn2020(10);

            [beta, u, info] = referenceSystem.orbitSunGeometry(r, v, epoch);

            for k = 1:10
                single = referenceSystem.daySecondToEpoch( ...
                    [epoch.day(k) epoch.sec(k)], epoch.scale);
                [betaOne, uOne, infoOne] = referenceSystem.orbitSunGeometry( ...
                    r(:, k), v(:, k), single);
                testCase.verifyEqual(betaOne, beta(k), 'AbsTol', 1e-15, ...
                    sprintf('beta of state %d is not the batch value.', k));
                testCase.verifyEqual(uOne, u(k), 'AbsTol', 1e-15, ...
                    sprintf('u of state %d is not the batch value.', k));
                testCase.verifyEqual(infoOne.uSun, info.uSun(k), ...
                    'AbsTol', 1e-15);
            end
        end

    end


    methods (Test, TestTags = {'speed'})

        function orbitSunGeometry_speed_oneDayOfDriverData(testCase)
            % The workload a calibration run actually asks for: one day of
            % orbit geometry at 60 s, which is the rate per-revolution
            % attribution needs, with the CIP equator so the precession-
            % nutation series is in the measurement.
            %
            % 0.051 s, SET FROM THE MEASURED MEDIAN AND NO LONGER FROM A
            % BOUND. Rev. 1.249 made referenceSystemCiGate echo the BENCHMARKS
            % table to the job log, which a CI-only session can fetch; the
            % report artefact, whose blob host the egress policy refuses, is no
            % longer the only copy. The rev. 1.247 bound of 0.078 s - all a
            % total wall time can yield - was pessimistic by 3.1x, and the
            % 0.20 s it justified was 8x the truth: a target that loose
            % detects nothing.
            %
            % 0.05 s WAS SET FROM TWO RUNS AND IS CORRECTED HERE BY THE THIRD.
            % The slowest of three medians is 0.025262 s, so twice it is
            % 0.050524 s and the rule gives 0.051, not 0.05. The difference
            % cannot fail a run and is corrected anyway, because a target that
            % is 1.98x the slowest measurement while claiming to be twice it
            % is the kind of small untruth this suite is built to not carry.
            % See the class help of TestPerformance for the runs and the rule.
            targetSeconds = 0.051;
            stateCount = 1440;
            [r, v] = TestOrbit.circularState(89, 30, ...
                (0:stateCount - 1)*360/stateCount);
            epoch = TestOrbit.epochIn2020(stateCount);

            medianSeconds = TestPerformance.medianDuration(@() ...
                referenceSystem.orbitSunGeometry(r, v, epoch), 3);

            testCase.log(matlab.unittest.Verbosity.Concise, ...
                TestPerformance.benchmarkRecord("orbitSunGeometry", ...
                stateCount, medianSeconds, targetSeconds));
            if medianSeconds > targetSeconds
                warning('referenceSystem:test:slowerThanTarget', ...
                    'orbitSunGeometry took %.3f s against a %.3f s target.', ...
                    medianSeconds, targetSeconds);
            end
            testCase.verifyLessThan(medianSeconds, 5*targetSeconds);
        end

    end


    methods (Static, Access = private)

        function epoch = j2000Epoch(count)
            %J2000EPOCH J2000.0 exactly, repeated count times, scale TT.
            %   MJD 51544 + 43200 s is 2000-01-01T12:00 TT. The day number is
            %   repeated and the seconds held, rather than a decimal MJD
            %   being used, for the reason epochAt states.
            epoch = referenceSystem.daySecondToEpoch( ...
                repmat([51544 43200], count, 1), "TT");
        end

        function epoch = epochIn2020(count)
            %EPOCHIN2020 A 60 s epoch series from 2020-01-01T00:00 TT.
            %   MJD 58849 is 2020-01-01. Sixty seconds is the rate at which
            %   per-revolution attribution consumes orbit geometry, and 1440
            %   of them is exactly one day.
            second = (0:count - 1).'*60;
            epoch = referenceSystem.daySecondToEpoch( ...
                [repmat(58849, count, 1), second], "TT");
        end

        function [r, v] = circularState(inclinationDegree, nodeDegree, ...
                argumentDegree)
            %CIRCULARSTATE A circular orbit state at each argument of latitude.
            %   Built from cos and sin around the node and orbit-normal
            %   directions, never through a package function, so a test does
            %   not compare the toolbox against itself. GRACE-like radius.
            radius = 6871000;
            speed = sqrt(3.986004418e14/radius);
            inclination = deg2rad(inclinationDegree);
            node = deg2rad(nodeDegree);
            argument = deg2rad(reshape(argumentDegree, 1, []));

            nodeAxis = [cos(node); sin(node); 0];
            normalAxis = [sin(inclination)*sin(node); ...
                -sin(inclination)*cos(node); cos(inclination)];
            aheadAxis = cross(normalAxis, nodeAxis);

            r = radius*(cos(argument).*nodeAxis + sin(argument).*aheadAxis);
            v = speed*(-sin(argument).*nodeAxis + cos(argument).*aheadAxis);
        end

        function [r, v] = referenceStates()
            %REFERENCESTATES The five states the numpy oracle was run on.
            %   Hardcoded to seventeen digits so the comparison never depends
            %   on MATLAB re-running the construction: i = 89 deg, RAAN = 30
            %   deg, circular at 6871 km, at u = 0, 45, 90, 180 and 270 deg.
            r = [ ...
                +5.95046054940287862e+06 +4.16521447949002916e+06 ...
                -5.99577423152874180e+04 -5.95046054940287862e+06 ...
                +5.99577423152866904e+04; ...
                +3.43549999999999953e+06 +2.50269828416725108e+06 ...
                +1.03849855997201113e+05 -3.43549999999999953e+06 ...
                -1.03849855997201536e+05; ...
                +0.00000000000000000e+00 +4.85779071577532124e+06 ...
                +6.86995351341956481e+06 +8.41326658050038379e-10 ...
                -6.86995351341956481e+06];
            v = [ ...
                -6.64636574225921493e+01 -4.71116879542230163e+03 ...
                -6.59613514769254562e+03 +6.64636574225913535e+01 ...
                +6.59613514769254562e+03; ...
                +1.15118431512781981e+02 -2.61145987415183436e+03 ...
                -3.80828040313144220e+03 -1.15118431512782450e+02 ...
                +3.80828040313144220e+03; ...
                +7.61540076716045223e+03 +5.38490152391239280e+03 ...
                +4.66308808686367272e-13 -7.61540076716045223e+03 ...
                -1.39892642605910171e-12];
        end

    end


